## Why This Is Asked
This question tests DP with a constrained path problem and reconstruction, a common real interview topic for large-scale environments like PayPal or Cloudflare.

## Key Concepts
- 4D DP state: i, j, t, dir (0 right, 1 down)
- Turn counting via transition from one dir to the other
- Base cases for first row/column
- Path reconstruction pointers and memory/time trade-offs

## Code Example
```javascript
function maxPathWithTurns(grid, k) {
  const n = grid.length, m = grid[0].length;
  const NEG = -1e15;
  const dp = Array.from({length: n}, () =>
    Array.from({length: m}, () =>
      Array.from({length: k+1}, () => [NEG, NEG])
    )
  );
  dp[0][0][0][0] = grid[0][0];
  for (let j = 1; j < m; j++) dp[0][j][0][0] = dp[0][j-1][0][0] + grid[0][j];
  for (let i = 1; i < n; i++) dp[i][0][0][1] = dp[i-1][0][0][1] + grid[i][0];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let t = 0; t <= k; t++) {
        if (j > 0) {
          const fromLeftSame = dp[i][j-1][t][0];
          const fromLeftTurn = t > 0 ? dp[i][j-1][t-1][1] : NEG;
          dp[i][j][t][0] = Math.max(dp[i][j][t][0], grid[i][j] + Math.max(fromLeftSame, fromLeftTurn));
        }
        if (i > 0) {
          const fromTopSame = dp[i-1][j][t][1];
          const fromTopTurn = t > 0 ? dp[i-1][j][t-1][0] : NEG;
          dp[i][j][t][1] = Math.max(dp[i][j][t][1], grid[i][j] + Math.max(fromTopSame, fromTopTurn));
        }
      }
    }
  }
  let best = NEG, bestT = 0, bestDir = 0;
  for (let t = 0; t <= k; t++) {
    for (let d = 0; d < 2; d++) {
      if (dp[n-1][m-1][t][d] > best) {
        best = dp[n-1][m-1][t][d]; bestT = t; bestDir = d;
      }
    }
  }
  return {best, bestT, bestDir};
}
```

## Follow-up Questions
- How would you reconstruct the path coordinates efficiently?
- Can you optimize memory to O(n*m*k) or O(k) with rolling arrays?

## Why This Is Asked
Tests partition DP with a subarray range cost, requiring precomputation of subarray extrema and careful reconstruction. It adds a different objective than prior questions by using (max-min) rather than a function of endpoints or a fixed multiplier. 

## Key Concepts
- DP over partitions with exact-k segments
- Subarray range queries (max-min) via precomputation
- Path reconstruction from parent pointers
- Time/space trade-offs for small to mid-size n

## Code Example
```javascript
function minCostPartition(A, k) {
  const n = A.length;
  const maxv = Array.from({length: n}, () => Array(n).fill(0));
  const minv = Array.from({length: n}, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    maxv[i][i] = A[i];
    minv[i][i] = A[i];
    for (let j = i + 1; j < n; j++) {
      maxv[i][j] = Math.max(maxv[i][j-1], A[j]);
      minv[i][j] = Math.min(minv[i][j-1], A[j]);
    }
  }
  const INF = 1e18;
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(INF));
  const par = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) dp[i][1] = (maxv[0][i-1]-minv[0][i-1]) * i, par[i][1] = 0;
  for (let t = 2; t <= k; t++) {
    for (let i = t; i <= n; i++) {
      for (let p = t-1; p <= i-1; p++) {
        const cost = (maxv[p][i-1]-minv[p][i-1]) * (i-p);
        if (dp[p][t-1] + cost < dp[i][t]) {
          dp[i][t] = dp[p][t-1] + cost;
          par[i][t] = p;
        }
      }
    }
  }
  let idx = n, rem = k, cuts = [];
  while (rem > 0) {
    const p = par[idx][rem];
    cuts.push([p, idx-1]);
    idx = p; rem--;
  }
  cuts.reverse();
  return {cost: dp[n][k], blocks: cuts};
}
```

## Why This Is Asked
This problem tests DP skills with an additional dimension for tracking turns while handling obstacles and grid boundaries. It verifies understanding of initialization logic, edge cases, and how to aggregate the final answer by summing across valid turn counts.

## Key Concepts
- 4D DP over cells, turn count, and last direction
- Turn counting via direction changes during transitions
- Correct handling of obstacles and grid boundaries
- Time/space trade-offs and proper base case logic

## Code Example
```javascript
function countPaths(grid, K) {
  const m = grid.length;
  const n = grid[0].length;
  if (grid[0][0] === 1 || grid[m-1][n-1] === 1) return 0;

  const dp = Array.from({ length: m }, () =>
    Array.from({ length: n }, () =>
      Array.from({ length: K + 1 }, () => [0, 0])
    )
  );

  dp[0][0][0][0] = 1; // right
  dp[0][0][0][1] = 1; // down

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) continue;
      for (let t = 0; t <= K; t++) {
        // from left (coming from right)
        if (j > 0) {
          dp[i][j][t][0] += dp[i][j-1][t][0]; // same direction
          if (t > 0) dp[i][j][t][0] += dp[i][j-1][t-1][1]; // turn
        }
        // from top (coming from down)
        if (i > 0) {
          dp[i][j][t][1] += dp[i-1][j][t][1]; // same direction
          if (t > 0) dp[i][j][t][1] += dp[i-1][j][t-1][0]; // turn
        }
      }
    }
  }

  let ans = 0;
  for (let t = 0; t <= K; t++) {
    ans += dp[m-1][n-1][t][0] + dp[m-1][n-1][t][1];
  }
  return ans;
}
```

This runs in O(m × n × K) time and O(m × n × K) space.

## Why This Is Asked
Tests DP formulation for selecting multiple non-overlapping subarrays, a common beginner challenge with practical reconstruction.

## Key Concepts
- dp[i][t]: best sum using first i elements with exactly t subarrays
- end[i][t]: best subarray sum ending at i-1 for t subarrays
- Transitions combine extending a subarray or starting a new one
- Reconstruction via backtracking boundaries

## Code Example
```javascript
function maxKSubarrays(A, k) {
  const n = A.length;
  const NEG = -Infinity;
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(NEG));
  const end = Array.from({length: n+1}, () => Array(k+1).fill(NEG));
  for (let i = 0; i <= n; i++) dp[i][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      end[i][t] = Math.max(end[i-1][t] + A[i-1], dp[i-1][t-1] + A[i-1]);
      dp[i][t] = Math.max(dp[i-1][t], end[i][t]);
    }
  }
  return {best: dp[n][k]};
}
```

## Follow-up Questions
- How would you adapt for at-most-k subarrays?
- How would you retrieve the actual subarray boundaries efficiently?

## Why This Is Asked

This question tests dynamic programming skills for selecting exactly k disjoint subarrays with a per-subarray penalty—a common variant in coding interviews that extends standard maximum subarray problems.

## Key Concepts

- **Non-overlapping constraint**: Subarrays must not intersect, handled by the state machine.
- **Dual-state DP**: Maintaining both global (dp) and local (end) states to track ongoing vs. completed selections.
- **Reconstruction**: Tracing back decisions to recover actual subarray endpoints.
- **Optimization**: Balancing time complexity (O(nk)) against space (full vs. rolling arrays).

## Code Example

```javascript
const solve = (A, k, c) => {
  const n = A.length;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const end = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const choice = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));

  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // Not taking a subarray ending at i
      if (dp[i-1][t] >= end[i][t]) {
        dp[i][t] = dp[i-1][t];
        choice[i][t] = 'skip';
      } else {
        dp[i][t] = end[i][t];
        choice[i][t] = 'end';
      }

      // Taking/starting subarray at i
      if (t > 0) {
        const startNew = dp[i-1][t-1] + A[i-1] - c;
        const extend = end[i-1][t] + A[i-1] - c;
        end[i][t] = Math.max(extend, startNew);
      }
    }
  }

  // Reconstruction logic would go here
  return { value: dp[n][k], subarrays: [] };
};
```

## Complexity

- **Time:** O(nk)
- **Space:** O(nk) for full DP, O(k) for optimized version

## Why This Is Asked
Tests DP state augmentation for a path with a constrained number of turns, combining path optimization with reconstruction. It demands careful handling of transitions when direction changes. 

## Key Concepts
- DP on grid paths with turn constraints
- 4D state dp[i][j][t][dir]
- Reconstruction via parent pointers
- Time: O(n*m*k); Space: O(n*m*k)

## Code Example
```javascript
function maxPathWithKTurns(grid, K) {
  const n = grid.length, m = grid[0].length;
  const NEG = -1e15;
  const dp = Array.from({length: n}, () =>
    Array.from({length: m}, () => Array.from({length: K+1}, () => [NEG, NEG]))
  );
  dp[0][0][0][0] = grid[0][0];
  dp[0][0][0][1] = grid[0][0];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      if (i === 0 && j === 0) continue;
      for (let t = 0; t <= K; t++) {
        const val = grid[i][j];
        if (j > 0) {
          dp[i][j][t][0] = Math.max(dp[i][j][t][0], dp[i][j-1][t][0] + val);
          if (t > 0) dp[i][j][t][0] = Math.max(dp[i][j][t][0], dp[i][j-1][t-1][1] + val);
        }
        if (i > 0) {
          dp[i][j][t][1] = Math.max(dp[i][j][t][1], dp[i-1][j][t][1] + val);
          if (t > 0) dp[i][j][t][1] = Math.max(dp[i][j][t][1], dp[i-1][j][t-1][0] + val);
        }
      }
    }
  }
  // reconstruction would backtrack using stored choices (omitted for brevity)
  return {dp, best: Math.max(...Array.from({length:K+1}, (_,t)=>Math.max(dp[n-1][m-1][t][0], dp[n-1][m-1][t][1])))};
}
```

## Why This Is Asked

Tests DP with a non-adjacent removal constraint and requires reconstruction of which indices were removed.

## Key Concepts

- 3D DP state dp[i][t][r]
- Non-adjacent constraint during removal
- Path reconstruction for the chosen indices

## Code Example

```javascript
function maxRemainingSum(A, k) {
  const n = A.length;
  const NEG = Number.NEGATIVE_INFINITY / 4;
  const dp = Array.from({ length: n + 1 }, () =>
    Array.from({ length: k + 1 }, () => [NEG, NEG])
  );
  dp[0][0][0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // keep i
      dp[i][t][0] = Math.max(dp[i-1][t][0], dp[i-1][t][1]) + A[i-1];
      // remove i
      if (t > 0) dp[i][t][1] = dp[i-1][t-1][0];
    }
  }
  return Math.max(dp[n][k][0], dp[n][k][1]);
}
```

